 package main
 // 解法1 time: O(N^2)
func jump(nums []int) int {
	step := 0
	//边界
	if nums == nil {
		return step
	}

	position := len(nums) - 1
	for position > 0 {
		for i := 0; i < position; i++ {
			if i+nums[i] > position {
				position = i
				step++
				break
			}
		}
	}
	return step
}

