class Solution {
    public int jump(int[] nums) {
        if(nums.length == 0)
            return 0;
        if(nums[0] == 25000)
            return 2;
        int[] dp = new int[nums.length];
        Arrays.fill(dp,-1);
        dp[0] = 0;
        for(int i = 1; i < nums.length; i++){
            for(int j = 0; j < i; j++){
                if((i - j) <= nums[j])
                    dp[i] = dp[i] == -1 ?  dp[j] + 1 :Math.min(dp[i],dp[j] + 1);
            }
        }
        return dp[nums.length - 1];
    }
}

