class Solution {
public:
    int jump(vector<int>& nums) {
        int i=0,lastjumppos=0,maxreach=0,jumps=0;
        int n=nums.size();
        while(lastjumppos<n-1)
        {
            maxreach=max(maxreach,i+nums[i]);
            if(i==lastjumppos)
            {
                lastjumppos=maxreach;
                jumps++;
            }
            i++;
        }
        return jumps;
    }
};

